00051 void Channel::update( std::map< CType, int > state )
00052 {
00053 
00054     for( std::list<Rule>::iterator rules_iter = rule_list.begin();
00055             rules_iter != rule_list.end();
00056             ++rules_iter ) {
00057         /* iterate over conditions, get the state of the condition type
00058          * and check if contion is met:
00059          *     if not -> go to next rule
00060          *        yes -> go to next condition
00061          * if all conditions are met: set channel active and return */
00062         bool probe = true;
00063 
00064         for( Rule::iterator cond_iter = rules_iter->begin();
00065                 cond_iter != rules_iter->end();
00066                 ++cond_iter ) {
00067             int sVal = state[cond_iter->type];
00068             if( !cond_iter->eval( cond_iter->rval, sVal ) ) {
00069                 probe = false;
00070                 break;
00071             }
00072         }
00073         if( probe ) {
00074             _active = true;
00075             return;
00076         }
00077     }
00078 
00079     _active = false;
00080 }
00081 
00082 void Channel::add( std::vector<Condition> rule )
00083 {
00084     rule_list.push_back( rule );
00085 }
