00087 static inline
00088 std::vector<std::string> &split( const std::string &s, char delim, std::vector<std::string> &elems )
00089 {
00090     std::stringstream ss( s );
00091     std::string item;
00092     while ( std::getline( ss, item, delim ) ) {
00093         elems.push_back( item );
00094     }
00095     return elems;
00096 }
00097 
00098 static inline
00099 std::vector<std::string> split( const std::string &s, char delim )
00100 {
00101     std::vector<std::string> elems;
00102     split( s, delim, elems );
00103     return elems;
00104 }
