00106 CDTrace::CDTrace( const char *filename, vstring channel_names )
00107     : copy(false), m_trace_file(NULL), m_error_code( 0 )
00108 {
00109     if( filename )
00110         m_trace_file = fopen( filename, "w" );
00111 
00112     int i = 0;
00113     for( vstring::iterator ci = channel_names.begin(); ci != channel_names.end(); ++ci ) {
00114         deserializationTable[*ci] = i++;
00115         chanRules.push_back( Channel() );
00116     }
00117 }
