00153 void CDTrace::swap( CDTrace& other )
00154 {
00155     using std::swap;
00156     CDTrace& first = *this;
00157     CDTrace& second = other;
00158     swap(first.copy,second.copy);
00159     swap(first.m_trace_file,second.m_trace_file);
00160     swap(first.chanRules,second.chanRules);
00161     swap(first.condition_types,second.condition_types);
00162     swap(first.state,second.state);
00163     swap(first.deserializationTable,second.deserializationTable);
00164 }
00165 
00166 CDTrace& CDTrace::operator=( const CDTrace& other )
00167 {
00168     CDTrace tmp(other);
00169     swap( tmp );
00170     return *this;
00171 }
