00179 bool _cf_eq ( int bound, int val ) { return ( val==bound ); }
00180 bool _cf_neq( int bound, int val ) { return ( val!=bound ); }
00181 bool _cf_le ( int bound, int val ) { return ( val<=bound ); }
00182 bool _cf_ge ( int bound, int val ) { return ( val>=bound ); }
00183 
00184 int CDTrace::addRule( std::string rulestring )
00185 {
00186     vstring chans_conds = split( rulestring, ':' );
00187     vstring channels = split( chans_conds[0], ',' );
00188     vstring conditions = split( chans_conds[1], ',' );
00189 
00190     /* parse the rules first */
00191     std::vector<Condition> rule;
00192     for( vstring::iterator ci = conditions.begin(); ci != conditions.end(); ++ci ) {
00193         /* find one of "==", "!=", "<=", ">=" */
00194         const char *ops_[] = { "==", "!=", "<=", ">=" };
00195         vstring operators( ops_,&ops_[sizeof( ops_ )/sizeof( ops_[0] )] );
00196         vstring::iterator oi = operators.begin();
00197         std::size_t pos = std::string::npos;
00198         do {
00199             if( ( pos = ci->find( *oi ) ) != std::string::npos ) break;
00200         } while( ++oi != operators.end() );
00201 
00202         /* No operator found, malformed rules string -> abort */
00203         if( pos == std::string::npos ) return -2;
00204 
00205         CType ctype( *ci,0,pos );
00206         int value = std::atoi( ci->substr( pos+2, ci->length()-( pos+2 ) ).c_str() );
00207         //if( condition_types.find( ctype ) == condition_types.end() ) return 0;
00208 
00209         /* partially apply the condition value to the associated
00210          * condtion function and append it to the rule */
00211         bool ( *cfunc )( int,int );
00212         if( "==" == *oi ) cfunc = _cf_eq;
00213         else if( "!=" == *oi ) cfunc = _cf_neq;
00214         else if( "<=" == *oi ) cfunc = _cf_le;
00215         else if( ">=" == *oi ) cfunc = _cf_ge;
00216         else return 0; // this is already taken care of
00217 
00218         rule.push_back( Condition( ctype, cfunc, value ) );
00219     }
00220 
00221     /* add the rule to each channel */
00222     for( vstring::iterator chan_iter = channels.begin(); chan_iter != channels.end(); ++chan_iter ) {
00223         std::map< Key, int>::iterator ichan = deserializationTable.find(*chan_iter);
00224         if( ichan != deserializationTable.end() )
00225             chanRules[ichan->second].add( rule );
00226         else
00227             return -3;
00228     }
00229 
00230     //return (int)channels.size();
00231     return 0;
00232 }
00233 
00234 bool CDTrace::update( state_type stateval )
00235 {
00236     state[stateval.first] = stateval.second;
00237 
00238     /* pass over all the channel rules */
00239     for( std::vector< Channel >::iterator citer = chanRules.begin(); citer != chanRules.end(); ++citer )
00240     {
00241         citer->update( state );
00242     }
00243 
00244     return true;
00245 }
00246 
00247 void CDTrace::getChannelsList( std::string& sChannels )
00248 {
00249   sChannels.clear();
00250   /* pass over all the channel rules */
00251   if( deserializationTable.size() > 0 )
00252   {
00253     for( channel_map_t::iterator it = deserializationTable.begin(); it != deserializationTable.end(); ++it )
00254       sChannels += it->first + "\n";
00255   }
00256 }
