00258 const char* CDTrace::getChannelName( int channel_number )
00259 {
00260   static const char not_found[] = "";
00261   if( deserializationTable.size() > 0 )
00262   {
00263     for( channel_map_t::iterator it = deserializationTable.begin(); it != deserializationTable.end(); ++it )
00264       if( it->second == channel_number )
00265         return it->first.c_str();
00266   }
00267   return not_found;
00268 }
