00270 std::string CDTrace::getErrMessage()
00271 {
00272   std::string str = "";
00273   if( m_error_code )
00274   {
00275     if( m_error_code == -2 )
00276       str = ( " - DTrace ERROR: Add tracing rule failed: DECERR_DTRACE_BAD_RULE" );
00277     else if( m_error_code == -3 )
00278       str = ( " - DTrace ERROR: Add tracing rule failed: DECERR_DTRACE_UNKNOWN_CHANNEL" );
00279     else
00280     {
00281       str = " - DTrace ERROR: Undefined error";
00282     }
00283   }
00284 
00285   return str;
00286 }
