00288 template< bool bCount>
00289 void CDTrace::dtrace( int k, const char *format, /*va_list args*/... )
00290 {
00291   if( m_trace_file && chanRules[k].active() )
00292   {
00293     va_list args;
00294     va_start ( args, format );
00295     vfprintf ( m_trace_file, format, args );
00296     fflush( m_trace_file );
00297     va_end ( args );
00298     if( bCount )
00299       chanRules[k].incrementCounter();
00300   }
00301   return;
00302 }
00303 
00304 template void CDTrace::dtrace<true>( int k, const char *format, /*va_list args*/... );
00305 template void CDTrace::dtrace<false>( int k, const char *format, /*va_list args*/... );
00306 
00307 void CDTrace::dtrace_repeat( int k, int i_times, const char *format, /*va_list args*/... )
00308 {
00309   if( m_trace_file && chanRules[k].active() )
00310   {
00311     va_list args;
00312     va_start( args, format );
00313     while( i_times > 0 )
00314     {
00315       i_times--;
00316       vfprintf( m_trace_file, format, args );
00317     }
00318     fflush( m_trace_file );
00319     va_end( args );
00320   }
00321   return;
00322 }
